"use strict";(self.webpackChunk_=self.webpackChunk_||[]).push([["5628"],{3902(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/StreamToolkitDocs/","label":"Stream Toolkit Introduction","docId":"intro","unlisted":false},{"type":"category","label":"Quick Start","items":[{"type":"link","href":"/StreamToolkitDocs/getting-started/installation","label":"Installation and Launch","docId":"getting-started/installation","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/getting-started/obs-source","label":"How to Add Sources in OBS","docId":"getting-started/obs-source","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/getting-started/trial-comparison","label":"Trial / Full Version Comparison","docId":"getting-started/trial-comparison","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Platform Settings","items":[{"type":"link","href":"/StreamToolkitDocs/platforms/youtube","label":"YouTube API Settings","docId":"platforms/youtube","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/platforms/youtube-settings","label":"YouTube Settings (New)","docId":"platforms/youtube-settings","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/platforms/twitch","label":"Twitch Settings","docId":"platforms/twitch","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Payment Settings","items":[{"type":"link","href":"/StreamToolkitDocs/payments/paypal","label":"PayPal Settings","docId":"payments/paypal","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/payments/stripe","label":"Stripe Settings","docId":"payments/stripe","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/payments/opay","label":"O\'Pay Settings","docId":"payments/opay","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/payments/ecpay","label":"ECPay Settings","docId":"payments/ecpay","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Third-Party Services","items":[{"type":"link","href":"/StreamToolkitDocs/services/deepl","label":"Obtaining DeepL API Key","docId":"services/deepl","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Feature Guides","items":[{"type":"link","href":"/StreamToolkitDocs/features/quick-tools","label":"Quick Tools","docId":"features/quick-tools","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/obs-scene","label":"OBS Scene Control","docId":"features/obs-scene","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/chat","label":"Chat","docId":"features/chat","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/voice-translate","label":"Voice Translation","docId":"features/voice-translate","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/multimedia","label":"Media Board","docId":"features/multimedia","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/highlight","label":"Stream Highlight Marker","docId":"features/highlight","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/donate","label":"Donation Goal Bar","docId":"features/donate","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/donate-alert","label":"Donation Alerts","docId":"features/donate-alert","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/sponsors","label":"Donation Board","docId":"features/sponsors","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/chat-bot","label":"Chat Bot","docId":"features/chat-bot","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/fan-alert","label":"New Follower Alerts","docId":"features/fan-alert","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/birthday-alert","label":"Viewer Birthday Alerts","docId":"features/birthday-alert","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/goal","label":"Twitch Goal Bar","docId":"features/goal","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/timer","label":"Timer","docId":"features/timer","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/clock","label":"Clock","docId":"features/clock","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/emote-wall","label":"Emote Wall","docId":"features/emote-wall","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/turntable","label":"Spin Wheel","docId":"features/turntable","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/vote","label":"Live Polls","docId":"features/vote","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/lottery","label":"Giveaways","docId":"features/lottery","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/song-request","label":"Song Requests","docId":"features/song-request","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/settings","label":"Settings","docId":"features/settings","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/themes","label":"Themes","docId":"features/themes","unlisted":false},{"type":"link","href":"/StreamToolkitDocs/features/hotkeys","label":"Hotkeys","docId":"features/hotkeys","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"features/birthday-alert":{"id":"features/birthday-alert","title":"Viewer Birthday Alerts","description":"Add your viewers\' birthdays to a list. When a listed viewer chats during your stream on or shortly after their birthday, a birthday alert pops up on stream. Each viewer gets one alert per birthday.","sidebar":"tutorialSidebar"},"features/chat":{"id":"features/chat","title":"Chat","description":"Chat shows your Twitch and YouTube chat together in one overlay, with optional auto-translation. It can also show chat in a transparent desktop window that only you can see.","sidebar":"tutorialSidebar"},"features/chat-bot":{"id":"features/chat-bot","title":"Chat Bot","description":"Posts messages in your chat automatically: timed messages at a set interval, and keyword replies when a viewer types a command. The bot posts from your own account.","sidebar":"tutorialSidebar"},"features/clock":{"id":"features/clock","title":"Clock","description":"Show the current time on stream, optionally with the date and weekday.","sidebar":"tutorialSidebar"},"features/donate":{"id":"features/donate","title":"Donation Goal Bar","description":"Shows a progress bar on stream toward a donation goal. Donations from the platforms you choose are added to the total automatically.","sidebar":"tutorialSidebar"},"features/donate-alert":{"id":"features/donate-alert","title":"Donation Alerts","description":"Pops up an alert with an image, sound, donor name, amount and message when someone donates.","sidebar":"tutorialSidebar"},"features/emote-wall":{"id":"features/emote-wall","title":"Emote Wall","description":"When viewers use emotes in chat, the emotes float across your stream.","sidebar":"tutorialSidebar"},"features/fan-alert":{"id":"features/fan-alert","title":"New Follower Alerts","description":"Pops up an alert on stream when someone follows you on Twitch or subscribes to your YouTube channel.","sidebar":"tutorialSidebar"},"features/goal":{"id":"features/goal","title":"Twitch Goal Bar","description":"Show progress bars on stream for your Twitch follower, subscription and Bits goals. Each goal type has its own bar, its own settings and its own OBS URL.","sidebar":"tutorialSidebar"},"features/highlight":{"id":"features/highlight","title":"Stream Highlight Marker","description":"Press a shortcut during your stream to record \\"how far into the stream\\" a highlight happened. Later you can use the list of times to find highlights in your VOD when editing.","sidebar":"tutorialSidebar"},"features/hotkeys":{"id":"features/hotkeys","title":"Hotkeys","description":"\u2328\uFE0F Hotkeys at the bottom of the left menu lists every hotkey you have set up, in one place.","sidebar":"tutorialSidebar"},"features/lottery":{"id":"features/lottery","title":"Giveaways","description":"Viewers join by typing a keyword in Twitch or YouTube chat. When entry closes, draw winners at random, and the draw animation plays on the OBS overlay.","sidebar":"tutorialSidebar"},"features/multimedia":{"id":"features/multimedia","title":"Media Board","description":"Show images, play videos and play sound effects on stream with a click or a shortcut.","sidebar":"tutorialSidebar"},"features/obs-scene":{"id":"features/obs-scene","title":"OBS Scene Control","description":"OBS Scene Control lets you switch scenes and show/hide sources in your streaming software with global hotkeys or from Quick Tools. It works with OBS Studio, Streamlabs and Meld Studio.","sidebar":"tutorialSidebar"},"features/quick-tools":{"id":"features/quick-tools","title":"Quick Tools","description":"Quick Tools is a small control window you can keep open next to your game or OBS. It lets you turn features on and off and use their most common controls without switching back to the main window.","sidebar":"tutorialSidebar"},"features/settings":{"id":"features/settings","title":"Settings","description":"Click \u2699\uFE0F Settings at the bottom of the left menu. This page holds app-wide options, platform connections, and donation payment gateways.","sidebar":"tutorialSidebar"},"features/song-request":{"id":"features/song-request","title":"Song Requests","description":"Viewers request YouTube songs with a chat command, and the songs play in OBS one after another. You can also add songs yourself and set a default playlist that plays when there are no requests.","sidebar":"tutorialSidebar"},"features/sponsors":{"id":"features/sponsors","title":"Donation Board","description":"Shows a list of recent donations on stream: platform icon, donor name, amount and message.","sidebar":"tutorialSidebar"},"features/themes":{"id":"features/themes","title":"Themes","description":"Share and download overlay looks through the Steam Workshop. A theme can include the appearance of these features:","sidebar":"tutorialSidebar"},"features/timer":{"id":"features/timer","title":"Timer","description":"Show countdown timers or stopwatches on stream. A countdown can gain or lose time from buttons you click, or automatically from Twitch follows, subs, Bits and donations.","sidebar":"tutorialSidebar"},"features/turntable":{"id":"features/turntable","title":"Spin Wheel","description":"Create your own prize wheels and spin them on stream. You can set each option\'s weight, the wheel colors, and whether a drawn option is removed afterward.","sidebar":"tutorialSidebar"},"features/voice-translate":{"id":"features/voice-translate","title":"Voice Translation","description":"Hold a shortcut and speak. Stream Toolkit turns your speech into text, translates it, and shows both lines as subtitles in OBS.","sidebar":"tutorialSidebar"},"features/vote":{"id":"features/vote","title":"Live Polls","description":"Run a poll on stream. Viewers vote by typing an option number in Twitch or YouTube chat, and the results update live on the OBS overlay.","sidebar":"tutorialSidebar"},"getting-started/installation":{"id":"getting-started/installation","title":"Installation and Launch","description":"System Requirements","sidebar":"tutorialSidebar"},"getting-started/obs-source":{"id":"getting-started/obs-source","title":"How to Add Sources in OBS","description":"Most features of Stream Toolkit require adding a \\"Browser Source\\" in OBS to display on your live stream.","sidebar":"tutorialSidebar"},"getting-started/trial-comparison":{"id":"getting-started/trial-comparison","title":"Trial / Full Version Comparison","description":"Stream Toolkit offers a free trial version and a full version. The trial version has no time limit and allows permanent use of most interactive features for a full experience, while the full version unlocks payment gateways, Steam Workshop, advanced customization, and removes various quantity limits.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Stream Toolkit Introduction","description":"The left menu is categorized by function. Beginners are recommended to start reading from Quick Start.","sidebar":"tutorialSidebar"},"payments/ecpay":{"id":"payments/ecpay","title":"ECPay Settings","description":"This tutorial explains how to obtain the HashKey and HashIV from ECPay and enter them into Stream Toolkit.","sidebar":"tutorialSidebar"},"payments/opay":{"id":"payments/opay","title":"O\'Pay Settings","description":"This tutorial explains how to obtain the HashKey and HashIV from O\'Pay and enter them into Stream Toolkit.","sidebar":"tutorialSidebar"},"payments/paypal":{"id":"payments/paypal","title":"PayPal Settings","description":"Stream Toolkit uses Webhooks to receive PayPal payment notifications, so there is no need to enter an API key.","sidebar":"tutorialSidebar"},"payments/stripe":{"id":"payments/stripe","title":"Stripe Settings","description":"Stream Toolkit receives Stripe payment notifications via Webhooks. The setup consists of two parts: obtaining the Webhook URL from the app, and completing the integration in the Stripe Dashboard.","sidebar":"tutorialSidebar"},"platforms/twitch":{"id":"platforms/twitch","title":"Twitch Settings","description":"Stream Toolkit uses OAuth authorization to connect your Twitch account, so there is no need to manually enter a key.","sidebar":"tutorialSidebar"},"platforms/youtube":{"id":"platforms/youtube","title":"YouTube API Settings","description":"This tutorial explains how to obtain the API Key and Channel ID for the YouTube Data API, used for the Stream Highlight Marker feature.","sidebar":"tutorialSidebar"},"platforms/youtube-settings":{"id":"platforms/youtube-settings","title":"YouTube Settings (New)","description":"Stream Toolkit connects your YouTube channel by signing in with Google, so there is no API key to create or enter.","sidebar":"tutorialSidebar"},"services/deepl":{"id":"services/deepl","title":"Obtaining DeepL API Key","description":"DeepL API Key is used for automatic translation of the following features:","sidebar":"tutorialSidebar"}}}}')}}]);